const hash = s => { let h = 2166136261; for (const c of String(s)) h = Math.imul(h ^ c.charCodeAt(0), 16777619) >>> 0; h ^= h >>> 15; h = Math.imul(h, 2246822507) >>> 0; h ^= h >>> 13; h = Math.imul(h, 3266489909) >>> 0; h ^= h >>> 16; return h >>> 0; };
export function kindIcon(name, kind) {
    const pal = PAL[kind] || PAL.other, h = hash(name), [a, b, fg] = pal[h % pal.length], id = `scf_${h.toString(36)}`;
    return `<defs><linearGradient id="${id}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${b}"/><stop offset="1" stop-color="${a}"/></linearGradient></defs><rect width="60" height="60" fill="url(#${id})"/>${(GLYPH[kind] || GLYPH.other)(fg || '#fff', a)}`;
}
// the icon of an app as an <svg>: its own icon when the catalog knows it, else its kind's tile
export const appIcon = (id, name, kind, size = 32) => `<svg class="sc_ic" aria-hidden="true" width="${size}" height="${size}" viewBox="0 0 60 60">${APP_ICONS[id] || kindIcon(name, kind)}</svg>`;
